import { mkdir, readFile, readdir, writeFile } from 'node:fs/promises'
import { join } from 'node:path'
import type { SessionMode } from './session-manager'

export type Hand = { sessionId: string; mode: SessionMode; feature?: string }

type Registry = { id: string; mode: SessionMode; feature?: string; files: Record<string, number> }

/** Where each session's own writes land, on disk so another session — another process, another window — can look them up: nothing here assumes they share memory. */
const dirFor = (workspaceRoot: string): string => join(workspaceRoot, '.agent', 'sessions')

/**
 * Attributes a file's content to the KiwiAgent session that last wrote it, so
 * a stale-write refusal can name who: this session's own writes go in here,
 * another session's are read back off disk. A thin attribution log, not the
 * fuller claim registry (deadlines, heartbeats, denying a live session's
 * hold) `docs/features/coordination.md#Claims` describes — nothing this
 * feature's rules ask for yet needs those.
 */
export class FileHands {
  constructor(
    private readonly workspaceRoot: string,
    private readonly sessionId: string,
    private readonly mode: SessionMode,
    private readonly feature: string | undefined,
  ) {}

  /** Records that this session's own write left `path` at `mtimeMs`. */
  async recordWrite(path: string, mtimeMs: number): Promise<void> {
    const dir = dirFor(this.workspaceRoot)
    const file = join(dir, `${this.sessionId}.json`)
    const registry: Registry = (await readRegistry(file)) ?? { id: this.sessionId, mode: this.mode, feature: this.feature, files: {} }
    registry.files[path] = mtimeMs
    await mkdir(dir, { recursive: true })
    await writeFile(file, JSON.stringify(registry), 'utf8').catch(() => undefined)
  }

  /** The other KiwiAgent session whose own write left `path` at exactly `mtimeMs`, if one did. */
  async whoWrote(path: string, mtimeMs: number): Promise<Hand | undefined> {
    let names: string[]
    try {
      names = await readdir(dirFor(this.workspaceRoot))
    } catch {
      return undefined
    }
    for (const name of names) {
      if (name === `${this.sessionId}.json`) continue
      const registry = await readRegistry(join(dirFor(this.workspaceRoot), name))
      if (registry && registry.files[path] === mtimeMs) return { sessionId: registry.id, mode: registry.mode, feature: registry.feature }
    }
    return undefined
  }
}

async function readRegistry(file: string): Promise<Registry | undefined> {
  try {
    return JSON.parse(await readFile(file, 'utf8')) as Registry
  } catch {
    return undefined
  }
}

/**
 * What a refusal or notice says about where a change came from: the other
 * KiwiAgent session and the feature it works on when the registry names one,
 * outside KiwiAgent otherwise — never which tool made the change.
 */
export function describeHand(hand: Hand | undefined): string {
  if (!hand) return 'It was changed from outside KiwiAgent.'
  const who = hand.feature ? `a KiwiAgent ${hand.mode} session on "${hand.feature}"` : `a KiwiAgent ${hand.mode} session`
  return `It was changed by ${who}.`
}

import { existsSync } from 'node:fs'
import { stat } from 'node:fs/promises'
import { isAbsolute, resolve } from 'node:path'
import { editedPath } from '../edits/edit-tools'
import { ReadTracker } from '../openai-session/tools/read-tracker'
import { describeHand, type FileHands } from './file-hands'
import type { PostToolUseOutcome, PreToolUseOutcome, SessionHooks, ToolUse } from './hooks'

const WRITE_TOOLS = new Set(['Write', 'Edit', 'MultiEdit', 'NotebookEdit'])

/**
 * Holds every session that writes — plan, implement, cleanup, chat, on either
 * engine — to the one check: a write to a file this session never read, or
 * that changed on disk since it did, is refused. Added once, unconditionally,
 * so no phase's instructions have to ask for it, and it reaches the Claude
 * engine's native Edit/Write the own loop's inline checks never could,
 * because it runs on the PreToolUse/PostToolUse pair every engine maps onto.
 */
export class StaleWriteGuard implements SessionHooks {
  private readonly files = new ReadTracker()

  constructor(
    private readonly cwd: string,
    private readonly hands: FileHands,
  ) {}

  async preToolUse(tool: ToolUse): Promise<PreToolUseOutcome> {
    const raw = writePath(tool)
    if (!raw) return undefined
    const path = this.abs(raw)
    // Writing a file that does not exist needs no prior read: there is nothing another hand could have changed.
    if (tool.toolName === 'Write' && !existsSync(path)) return undefined
    const reason = await this.files.staleness(path)
    if (!reason) return undefined
    const hand = existsSync(path) ? await this.hands.whoWrote(path, (await stat(path)).mtimeMs) : undefined
    return { deny: `${reason} ${describeHand(hand)}` }
  }

  async postToolUse(tool: ToolUse & { isError: boolean }): Promise<PostToolUseOutcome> {
    if (tool.isError) return undefined
    const raw = writePath(tool) ?? readPath(tool)
    if (!raw) return undefined
    const path = this.abs(raw)
    if (!existsSync(path)) return undefined
    // The session's own write counts as seeing the file, so the next edit in a row is never refused.
    await this.files.markRead(path)
    if (WRITE_TOOLS.has(tool.toolName)) await this.hands.recordWrite(path, (await stat(path)).mtimeMs)
    return undefined
  }

  private abs(path: string): string {
    return isAbsolute(path) ? path : resolve(this.cwd, path)
  }
}

function writePath(tool: ToolUse): string | undefined {
  return WRITE_TOOLS.has(tool.toolName) ? editedPath(tool.input) : undefined
}

function readPath(tool: ToolUse): string | undefined {
  if (tool.toolName !== 'Read') return undefined
  const input = tool.input
  const value = typeof input === 'object' && input !== null ? (input as Record<string, unknown>)['file_path'] : undefined
  return typeof value === 'string' ? value : undefined
}

